27	/**
28	 * Simple JavaBean domain object representing an owner.
29	 *
30	 * @author Ken Krebs
31	 * @author Juergen Hoeller
32	 * @author Sam Brannen
33	 * @author Michael Isvy
34	 */
35	@Entity
36	@Table(name = "owners")
37	public class Owner extends Person {
38	    @Column(name = "address")
39	    @NotEmpty
40	    private String address;
41	
42	    @Column(name = "city")
43	    @NotEmpty
44	    private String city;
45	
46	    @Column(name = "telephone")
47	    @NotEmpty
48	    @Pattern(regexp = "^\\+[0-9]{8,15}$", message = "Phone number must be in E.164 form (+ followed by 8 to 15 digits)")
49	    private String telephone;
50	
51	    @Column(name = "email")
52	    private String email;
53	
54	    @Column(name = "registration_date", columnDefinition = "DATE")
55	    private LocalDate registrationDate;
56	
57	    @Column(name = "customer_code")
58	    private String customerCode;
59	
60	    @Column(name = "household_id")
61	    private String householdId;
62	
63	    @Column(name = "namesake_count")
64	    private Integer namesakeCount;
65	
66	    @OneToMany(cascade = CascadeType.ALL, mappedBy = "owner", fetch = FetchType.EAGER)
67	    private Set<Pet> pets;
68	
69	    public String getAddress() {
70	        return this.address;
71	    }
72	
73	    public void setAddress(String address) {
74	        this.address = address;
75	    }
76	
77	    public String getCity() {
78	        return this.city;
79	    }
80	
81	    public void setCity(String city) {
82	        this.city = city;
83	    }
84	
85	    public String getTelephone() {
86	        return this.telephone;
87	    }
88	
89	    public void setTelephone(String telephone) {
90	        this.telephone = telephone;
91	    }
92	
93	    public String getEmail() {
94	        return this.email;
95	    }
96	
97	    public void setEmail(String email) {
98	        this.email = email == null ? null : email.toLowerCase();
99	    }
100	
101	    public LocalDate getRegistrationDate() {
102	        return this.registrationDate;
103	    }
104	
105	    public void setRegistrationDate(LocalDate registrationDate) {
106	        this.registrationDate = registrationDate;
107	    }
108	
109	    public String getCustomerCode() {
110	        return this.customerCode;
111	    }
112	
113	    public void setCustomerCode(String customerCode) {
114	        this.customerCode = customerCode;
115	    }
116	
117	    public String getHouseholdId() {
118	        return this.householdId;
119	    }
120	
121	    public void setHouseholdId(String householdId) {
122	        this.householdId = householdId;
123	    }
124	
125	    public Integer getNamesakeCount() {
126	        return this.namesakeCount;
127	    }
128	
129	    public void setNamesakeCount(Integer namesakeCount) {
130	        this.namesakeCount = namesakeCount;
131	    }
132	
133	    /**
134	     * Defaults the registration date to the server's current date when none was supplied,
135	     * so the create-time default applies to any persistence path.
136	     */
137	    @PrePersist
138	    protected void defaultRegistrationDate() {
139	        if (this.registrationDate == null) {
140	            this.registrationDate = LocalDate.now();
141	        }
142	    }
143	
144	    protected Set<Pet> getPetsInternal() {
145	        if (this.pets == null) {
146	            this.pets = new HashSet<>();
147	        }
148	        return this.pets;
149	    }
150	
151	    protected void setPetsInternal(Set<Pet> pets) {
152	        this.pets = pets;
153	    }
154	
155	    public List<Pet> getPets() {
156	        List<Pet> sortedPets = new ArrayList<>(getPetsInternal());
157	        sortedPets.sort(Comparator.comparing(Pet::getName, String.CASE_INSENSITIVE_ORDER));
158	        return Collections.unmodifiableList(sortedPets);
159	    }
160	
161	    public void setPets(List<Pet> pets) {
162	        this.pets = new HashSet<>(pets);
163	    }
164	
165	    public void addPet(Pet pet) {
166	        getPetsInternal().add(pet);
167	        pet.setOwner(this);
168	    }
169	
170	    /**
171	     * Return the Pet with the given name, or null if none found for this Owner.
172	     *
173	     * @param name to test
174	     * @return true if pet name is already in use
175	     */
176	    public Pet getPet(String name) {
177	        return getPet(name, false);
178	    }
179	
180	    /**
181	     * Return the Pet with the given name, or null if none found for this Owner.
182	     *
183	     * @param name to test
184	     * @return true if pet name is already in use
185	     */
186	    public Pet getPet(String name, boolean ignoreNew) {
187	        name = name.toLowerCase();
188	        for (Pet pet : getPetsInternal()) {
189	            if (!ignoreNew || !pet.isNew()) {
190	                String compName = pet.getName();
